/// One `--text-*` style of styles.css @theme. Line height is absolute px; weight and
/// letter spacing (em, multiply by the font size) are null when the style does not set them.
@immutable
class RaftTypeStyle {
  const RaftTypeStyle(this.fontSize, this.lineHeight, {this.fontWeight, this.letterSpacingEm});
  final double fontSize;
  final double lineHeight;
  final int? fontWeight;
  final double? letterSpacingEm;
  /// Flutter `TextStyle.height` factor.
  double get height => lineHeight / fontSize;
}

